public sealed class CsvDataAttribute(string path) : DataAttribute
{
    public override ValueTask<IReadOnlyCollection<ITheoryDataRow>> GetData(
        MethodInfo testMethod, DisposalTracker disposalTracker)
    {
        IReadOnlyCollection<ITheoryDataRow> rows = File.ReadLines(path)
            .Select(l => new TheoryDataRow(l.Split(','))).ToArray();
        return new ValueTask<IReadOnlyCollection<ITheoryDataRow>>(rows);
    }
}
